css:
#mv-layout-library{--mv-navy:#153b4b;--mv-ink:#173945;--mv-muted:#54707b;--mv-blue:#38bbdf;--mv-pale:#e9f7fb;--mv-line:#dce7eb;--mv-shadow:0 14px 38px #163f4b0d;font-family:Arial,Helvetica,sans-serif;color:var(--mv-ink);background:#f4f7f8;font-size:16px;line-height:1.65;text-align:left;isolation:isolate;overflow-wrap:break-word}
#mv-layout-library *,#mv-layout-library *:before,#mv-layout-library *:after{box-sizing:border-box}
#mv-layout-library [hidden]{display:none!important}
#mv-layout-library :is(h1,h2,h3,h4,p,figure,blockquote,dl,dd,ul){margin:0;padding:0;font-family:inherit;color:inherit}
#mv-layout-library :is(h1,h2,h3,h4){font-weight:750;line-height:1.13;letter-spacing:-.035em;text-transform:none}
#mv-layout-library :is(button,input,textarea,select){font:inherit;letter-spacing:normal}
#mv-layout-library :is(button,a,input,textarea,select):focus-visible{outline:3px solid #1685a5;outline-offset:5px}
#mv-layout-library :is(button,a){-webkit-tap-highlight-color:transparent}
#mv-layout-library a{color:inherit;text-decoration:none;box-shadow:none}
#mv-layout-library button{cursor:pointer;border:0;box-shadow:none;text-transform:none;line-height:1.35}
#mv-layout-library button:hover{filter:brightness(.96)}
#mv-layout-library .mv-toolbar{position:sticky;top:0;z-index:10;background:#153b4bf5;color:white;backdrop-filter:blur(14px);padding:15px 4%;display:flex;gap:22px;align-items:center;box-shadow:0 3px 20px #102b3612}
#mv-layout-library .mv-brand{font-size:14px;font-weight:700;letter-spacing:.04em;white-space:nowrap}
#mv-layout-library .mv-brand span{display:inline-flex;align-items:center;justify-content:center;width:29px;height:29px;background:var(--mv-blue);color:var(--mv-navy);border-radius:7px;margin-right:9px}
#mv-layout-library .mv-toolbar-controls{margin-left:auto;display:flex;align-items:center;gap:20px;font-size:12px}
#mv-layout-library .mv-toolbar label{display:flex;gap:8px;align-items:center;color:inherit;margin:0}
#mv-layout-library .mv-toolbar select{max-width:250px;background:#244d5c;color:white;border:1px solid #54707b;border-radius:6px;padding:8px;font-size:12px;height:auto;min-height:0}
#mv-layout-library .mv-toolbar input{width:15px;height:15px;accent-color:var(--mv-blue);margin:0}
#mv-layout-library .mv-print{background:transparent;color:#fff;border:1px solid #54707b;border-radius:6px;padding:8px 12px;font-size:12px}
#mv-layout-library .mv-shell{max-width:1440px;margin:auto;padding:0 4%}
#mv-layout-library .mv-library-intro{padding:72px 0 44px;display:grid;grid-template-columns:1.3fr 1fr;gap:65px;align-items:end}
#mv-layout-library .mv-library-intro h1{font-size:clamp(34px,4.7vw,66px);line-height:1.02;margin:16px 0 0;max-width:730px}
#mv-layout-library .mv-library-intro p{color:var(--mv-muted);font-size:15px;max-width:460px}
#mv-layout-library .mv-overline{font-size:11px!important;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--mv-muted)}
#mv-layout-library .mv-meta{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0 0}
#mv-layout-library .mv-meta span{border:1px solid #ccdce1;border-radius:4px;padding:5px 9px;font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--mv-muted)}
#mv-layout-library .mv-index{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0 28px;border-top:1px solid #ccdce1;border-bottom:1px solid #ccdce1;padding:15px 0;margin-bottom:66px}
#mv-layout-library .mv-index a{font-size:12px;display:flex;align-items:center;gap:10px;padding:8px 0;line-height:1.4}
#mv-layout-library .mv-index a:hover{color:#1685a5}
#mv-layout-library .mv-index span{color:#79919b;font-size:10px;flex-shrink:0;font-variant-numeric:tabular-nums}
#mv-layout-library .mv-specimen{margin:0 0 64px;scroll-margin-top:100px}
#mv-layout-library .mv-specimen-heading{display:flex;align-items:center;gap:15px;margin-bottom:10px}
#mv-layout-library .mv-number{background:white;border:1px solid #d2e0e4;width:42px;height:46px;border-radius:8px;display:grid;place-items:center;font-size:15px;color:#587580;font-variant-numeric:tabular-nums}
#mv-layout-library .mv-category{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.13em;color:#718b95;margin-bottom:5px}
#mv-layout-library .mv-specimen-heading h2{font-size:21px;letter-spacing:-.02em}
#mv-layout-library .mv-permalink{margin-left:auto;font-size:18px;color:#8098a1;padding:8px}
#mv-layout-library .mv-note{font-size:12px;color:#647f89;margin:0 0 10px 57px}
#mv-layout-library .mv-sources{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:0 0 18px 57px;font-size:10px;line-height:1.4}
#mv-layout-library .mv-sources>span{font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:#718b95;margin-right:4px}
#mv-layout-library .mv-sources a{display:inline-flex;align-items:center;gap:9px;border:1px solid #d3e1e6;background:#ffffffa6;padding:5px 9px;border-radius:5px;color:#3c697c}
#mv-layout-library .mv-sources a span{font-size:10px;color:#72919f}
#mv-layout-library .mv-sources a:hover{background:#e0f3f9;border-color:#9ec9d8;color:#174e64}
#mv-layout-library.mv-hide-notes .mv-note{display:none}
#mv-layout-library .mv-demo{background:white;border:1px solid #d8e3e7;border-radius:16px;overflow:hidden;box-shadow:var(--mv-shadow)}
#mv-layout-library .mv-pad{padding:70px 6%}
#mv-layout-library .mv-centered{text-align:center}
#mv-layout-library .mv-demo .mv-eyebrow{font-size:11px;font-weight:700;letter-spacing:.13em;color:#239fbe;text-transform:uppercase;margin-bottom:14px;line-height:1.4}
#mv-layout-library .mv-display{font-size:clamp(34px,4.4vw,62px);line-height:1.05;letter-spacing:-.045em}
#mv-layout-library .mv-title{font-size:clamp(26px,2.7vw,38px);line-height:1.14;margin-bottom:23px;letter-spacing:-.035em}
#mv-layout-library .mv-lead{font-size:clamp(16px,1.6vw,21px);color:var(--mv-muted);line-height:1.65;margin-top:23px}
#mv-layout-library .mv-demo p:not(.mv-eyebrow):not(.mv-demo-disclaimer):not(.mv-media-kicker){margin-bottom:19px}
#mv-layout-library .mv-demo p:last-child{margin-bottom:0}
#mv-layout-library .mv-demo p{color:var(--mv-muted)}
#mv-layout-library .mv-button{display:inline-flex;gap:24px;align-items:center;justify-content:center;background:var(--mv-blue);color:#113847;border:2px solid transparent;border-radius:7px;padding:13px 23px;font-size:13px;line-height:1.4;font-weight:700;min-height:48px;transition:background .15s}
#mv-layout-library .mv-button:hover{background:#7ad2e9}
#mv-layout-library .mv-button.mv-secondary{background:transparent;border-color:#32677b;color:#234e60}
#mv-layout-library .mv-actions{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;margin-top:30px}
#mv-layout-library .mv-hero-light{background:linear-gradient(165deg,#fff,#e0f3f9)}
#mv-layout-library .mv-hero-light.mv-centered{padding-top:86px;padding-bottom:90px}
#mv-layout-library .mv-split{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:7%}
#mv-layout-library .mv-down{display:inline-grid;place-items:center;font-size:35px;font-weight:400;line-height:1;margin-top:16px;width:44px;height:44px;color:var(--mv-blue)}
#mv-layout-library .mv-curved{border-radius:0 0 50% 6% / 0 0 6% 2%}
#mv-layout-library .mv-image{position:relative;aspect-ratio:4/3;overflow:hidden;background:#e6eef0;border-radius:22px;min-width:0}
#mv-layout-library .mv-image svg{display:block;width:100%;height:100%;position:absolute;inset:0}
#mv-layout-library .mv-image>span{position:absolute;left:18px;right:18px;bottom:17px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#35535f;background:#ffffffbf;backdrop-filter:blur(5px);border-radius:5px;padding:9px 12px;display:flex;justify-content:space-between;gap:10px}
#mv-layout-library .mv-image>span b{font-weight:400;opacity:.7}
#mv-layout-library .mv-image-backdrop{position:relative;margin:20px 0;z-index:0}
#mv-layout-library .mv-image-backdrop:before{content:"";position:absolute;inset:-15px 7px;background:#bce8f3;border-radius:32px;transform:rotate(9deg);z-index:-1}
#mv-layout-library .mv-background-hero{position:relative;min-height:440px;display:grid;place-items:center}
#mv-layout-library .mv-background-hero>.mv-image{position:absolute;inset:0;border-radius:0;aspect-ratio:auto}
#mv-layout-library .mv-background-hero>.mv-image>span{display:none}
#mv-layout-library .mv-hero-overlay{position:absolute;inset:0;background:linear-gradient(140deg,#102f40df,#174e64cb)}
#mv-layout-library .mv-hero-copy{position:relative;max-width:950px;color:white}
#mv-layout-library .mv-hero-copy .mv-lead{color:#e6f3f7;max-width:700px;margin:22px auto 10px}
#mv-layout-library .mv-hero-copy .mv-eyebrow{color:#7bd8ef}
#mv-layout-library .mv-hero-copy .mv-down{color:white}
#mv-layout-library .mv-photo-intro{padding:42px 6% 0}
#mv-layout-library .mv-photo-intro-image .mv-image{aspect-ratio:16/7;border-radius:20px 20px 0 0}
#mv-layout-library .mv-intro-copy{padding:50px 8% 55px;background:white}
#mv-layout-library .mv-intro-copy p{max-width:830px;margin:24px auto 0}
#mv-layout-library .mv-media-wrap{padding:42px 6%;background:linear-gradient(#e9f7fb,#fff)}
#mv-layout-library .mv-media{position:relative;aspect-ratio:16/8;min-height:310px;background:#173c4e;border-radius:24px;overflow:hidden;color:white;display:grid;place-items:center}
#mv-layout-library .mv-media-art{position:absolute;inset:0;overflow:hidden;background:linear-gradient(150deg,#153644,#295b6e)}
#mv-layout-library .mv-media-art>span{position:absolute;width:38%;aspect-ratio:1;border:1px solid #8dc9d145;transform:rotate(35deg);border-radius:22%;animation:mv-media-drift 14s ease-in-out infinite alternate}
#mv-layout-library .mv-media-art>span:nth-child(1){left:-8%;top:10%;background:#44b7cb1a}
#mv-layout-library .mv-media-art>span:nth-child(2){left:17%;top:50%;animation-delay:-5s}
#mv-layout-library .mv-media-art>span:nth-child(3){right:9%;top:-30%;background:#44b7cb1a;animation-delay:-8s}
#mv-layout-library .mv-media-art>span:nth-child(4){right:-15%;bottom:-40%;animation-delay:-3s}
#mv-layout-library .mv-media-center{position:relative;text-align:center;padding:45px 25px 85px}
#mv-layout-library .mv-media-kicker{color:#8cbed0;font-size:10px;letter-spacing:.17em;margin-bottom:16px}
#mv-layout-library .mv-media-center h3{font-size:clamp(24px,3vw,43px)}
#mv-layout-library .mv-media-center p{font-size:14px;color:#bcd2db;margin-top:18px}
#mv-layout-library .mv-media-bottom{position:absolute;bottom:0;left:0;right:0;background:#102c3980;padding:16px 22px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:10px;color:#c0d5de}
#mv-layout-library .mv-media-bottom i{width:6px;height:6px;border-radius:50%;background:#6bd4e4;display:inline-block;margin-right:6px}
#mv-layout-library .mv-media-toggle{background:transparent;color:white;border:1px solid #799cae;border-radius:5px;padding:7px 10px;font-size:10px}
#mv-layout-library .mv-media.mv-paused .mv-media-art>span{animation-play-state:paused}
#mv-layout-library .mv-tint{background:linear-gradient(145deg,#eef9fb,#e7f4f8)}
#mv-layout-library .mv-panels{padding:52px 6%;display:grid;gap:35px}
#mv-layout-library .mv-service-panel{display:grid;grid-template-columns:1fr 1fr;background:white;border-radius:24px;overflow:hidden;align-items:stretch}
#mv-layout-library .mv-service-panel>.mv-image{border-radius:0;aspect-ratio:auto;min-height:350px}
#mv-layout-library .mv-panel-copy{padding:42px 36px}
#mv-layout-library .mv-panel-copy .mv-title{font-size:30px}
#mv-layout-library .mv-panel-copy p{font-size:14px}
#mv-layout-library .mv-features{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:7px 14px;margin:25px 0!important;color:var(--mv-muted);font-size:13px}
#mv-layout-library .mv-features li:before{content:"✦";color:var(--mv-blue);margin-right:8px}
#mv-layout-library .mv-service-panel.mv-reverse>.mv-image{order:2}
#mv-layout-library .mv-illustration-list{display:grid;gap:65px}
#mv-layout-library .mv-illustration-row{display:grid;grid-template-columns:30% 1fr;gap:8%;align-items:center}
#mv-layout-library .mv-illustration-row.mv-reverse{grid-template-columns:1fr 30%}
#mv-layout-library .mv-illustration-row.mv-reverse>.mv-illustration{order:2}
#mv-layout-library .mv-illustration{aspect-ratio:1;border-radius:45% 55% 42% 58% / 60% 48% 52% 40%;display:grid;place-items:center;background:#edf9fc;color:#39b8dc}
#mv-layout-library .mv-illustration .mv-icon{width:63%;height:63%}
#mv-layout-library .mv-tone-2{background:#f0f7ef;color:#7ba977}
#mv-layout-library .mv-icon{display:block;width:48px;height:48px}
#mv-layout-library .mv-capabilities-wrap{padding:45px 5%}
#mv-layout-library .mv-capabilities{background:white;border-radius:28px;padding:50px;display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:6%;box-shadow:var(--mv-shadow)}
#mv-layout-library .mv-capabilities .mv-image{aspect-ratio:4/2.6;border-radius:17px;margin-top:28px}
#mv-layout-library .mv-capabilities .mv-title{font-size:31px}
#mv-layout-library .mv-link-list a{display:flex;align-items:center;gap:16px;padding:23px 0;border-bottom:1px solid #e4eef1;font-weight:700;font-size:17px}
#mv-layout-library .mv-link-list a:last-child{border-bottom:0}
#mv-layout-library .mv-link-list a:hover{color:#1685a5}
#mv-layout-library .mv-link-icon{padding:10px;border-radius:12px;background:#f0f9fb;color:#66c3dc}
#mv-layout-library .mv-link-icon svg{width:38px;height:38px}
#mv-layout-library .mv-link-list b{margin-left:auto;background:var(--mv-blue);border-radius:50%;display:grid;place-items:center;width:29px;height:29px;color:white;font-size:17px;font-weight:400;flex-shrink:0}
#mv-layout-library .mv-team-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;max-width:790px;margin:38px auto 0}
#mv-layout-library .mv-person{border-radius:18px;overflow:hidden;background:#21566d;color:white}
#mv-layout-library .mv-portrait{position:relative;aspect-ratio:1;overflow:hidden}
#mv-layout-library .mv-portrait svg{display:block;width:100%;height:100%}
#mv-layout-library .mv-portrait>span{position:absolute;bottom:13px;left:0;right:0;font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:#516d77}
#mv-layout-library .mv-person>div:last-child{padding:24px 15px}
#mv-layout-library .mv-person h4{font-size:22px;letter-spacing:-.02em}
#mv-layout-library .mv-person p{color:#c7e2ed;margin:9px 0 12px!important;font-size:13px}
#mv-layout-library .mv-text-button{background:none;color:#9cdeed;border-bottom:1px solid #72a8bc;padding:4px 0;font-size:12px;border-radius:0}
#mv-layout-library .mv-image-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:37px}
#mv-layout-library .mv-image-card{display:block;border-radius:18px;overflow:hidden;background:var(--mv-navy);color:white}
#mv-layout-library .mv-image-card .mv-image{border-radius:0;aspect-ratio:4/2.6}
#mv-layout-library .mv-image-card>span{display:flex;align-items:center;justify-content:center;gap:17px;padding:20px;font-size:18px;font-weight:700}
#mv-layout-library .mv-image-card>span b{font-size:25px;font-weight:400;transition:transform .2s}
#mv-layout-library .mv-image-card:hover>span b{transform:translateX(6px)}
#mv-layout-library .mv-qa-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:36px;text-align:left}
#mv-layout-library .mv-qa{background:white;border-radius:24px;padding:39px;box-shadow:0 15px 30px #244c5b0b}
#mv-layout-library .mv-qa h4{font-size:23px;letter-spacing:-.025em;margin-bottom:22px}
#mv-layout-library .mv-qa p{font-size:15px}
#mv-layout-library .mv-carousel{display:grid;grid-template-columns:42px 1fr 42px;gap:20px;align-items:center;margin-top:40px}
#mv-layout-library .mv-carousel>button{width:42px;height:42px;border:1px solid #bcdce5;background:#ffffff90;color:#259abc;border-radius:50%;font-size:23px;padding:0}
#mv-layout-library .mv-slide{max-width:790px;margin:auto}
#mv-layout-library .mv-avatar{width:65px;height:65px;background:#d2e7ec;color:#5a8493;border-radius:50%;display:grid;place-items:center;margin:0 auto 27px;font-size:44px;line-height:1}
#mv-layout-library blockquote{font-size:clamp(17px,1.8vw,23px);line-height:1.75;color:var(--mv-muted)}
#mv-layout-library .mv-attribution{margin-top:25px}
#mv-layout-library .mv-attribution strong{display:block;color:#239fbe;font-size:15px}
#mv-layout-library .mv-attribution span{display:block;font-size:12px;margin-top:4px}
#mv-layout-library .mv-sample-logo{display:inline-block;font-size:11px;letter-spacing:.12em;color:#617c87;margin-top:10px}
#mv-layout-library .mv-dots{display:flex;justify-content:center;gap:9px;margin-top:34px}
#mv-layout-library .mv-dots button{width:11px;height:11px;border-radius:50%;background:#bed5dc;padding:0}
#mv-layout-library .mv-dots button[aria-pressed=true]{background:#2baecf}
#mv-layout-library .mv-demo-disclaimer{font-size:10px;line-height:1.6;color:#6e8791;margin-top:22px}
#mv-layout-library .mv-logo-window{overflow:hidden;margin:38px -1% 27px;mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}
#mv-layout-library .mv-logo-track{display:flex;width:max-content;animation:mv-logo-drift 35s linear infinite}
#mv-layout-library .mv-logo-track-reverse{animation-direction:reverse;margin-top:19px}
#mv-layout-library .mv-logo,#mv-layout-library .mv-logo-duplicates{display:flex;align-items:center}
#mv-layout-library .mv-logo{width:175px;justify-content:center;gap:10px;white-space:nowrap;color:#7e969f;font-size:15px;font-weight:700;letter-spacing:.06em;height:63px}
#mv-layout-library .mv-logo b{font-size:29px;font-weight:400;color:#a2b6bd}
#mv-layout-library .mv-logos-section.mv-paused .mv-logo-track,#mv-layout-library .mv-logo-window:hover .mv-logo-track{animation-play-state:paused}
#mv-layout-library .mv-small-button{font-size:10px;border:1px solid #cedfe5;border-radius:5px;background:white;color:#567480;padding:9px 13px}
#mv-layout-library .mv-filters{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin:30px 0}
#mv-layout-library .mv-filters button,#mv-layout-library .mv-pagination button{font-size:11px;border:1px solid #c6dee6;border-radius:5px;background:white;color:#52707c;padding:8px 15px}
#mv-layout-library .mv-filters button[aria-pressed=true],#mv-layout-library .mv-pagination button[aria-pressed=true]{background:var(--mv-blue);color:#123d4d;border-color:var(--mv-blue)}
#mv-layout-library .mv-article-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
#mv-layout-library .mv-article{background:white;border-radius:14px;overflow:hidden;display:flex;flex-direction:column}
#mv-layout-library .mv-article-image{position:relative}
#mv-layout-library .mv-article .mv-image{aspect-ratio:4/2.6;border-radius:0}
#mv-layout-library .mv-article .mv-image>span{display:none}
#mv-layout-library .mv-badge{position:absolute;top:12px;left:12px;border-radius:30px;background:#e9f8fbe8;color:#38687b;font-size:9px;padding:4px 9px}
#mv-layout-library .mv-article-copy{padding:24px;display:flex;flex-direction:column;flex-grow:1}
#mv-layout-library .mv-article h4{font-size:21px;margin-bottom:15px;letter-spacing:-.025em}
#mv-layout-library .mv-article p{font-size:12px;line-height:1.8;margin-bottom:22px!important}
#mv-layout-library .mv-article button{align-self:flex-start;margin-top:auto;color:#287f99;font-weight:700;letter-spacing:.06em;font-size:10px}
#mv-layout-library .mv-pagination{display:flex;gap:8px;justify-content:center;margin-top:30px}
#mv-layout-library .mv-contact{display:grid;grid-template-columns:1fr 1fr;gap:6%;align-items:start}
#mv-layout-library .mv-form{background:white;box-shadow:var(--mv-shadow);border-radius:22px;padding:34px;margin:0;min-width:0}
#mv-layout-library .mv-form .mv-title,#mv-layout-library .mv-information .mv-title{font-size:29px;margin-bottom:12px}
#mv-layout-library .mv-form .mv-demo-disclaimer{margin:0 0 23px}
#mv-layout-library .mv-fields{display:grid;grid-template-columns:1fr 1fr;gap:17px}
#mv-layout-library .mv-fields label{font-size:11px;font-weight:700;color:var(--mv-ink);display:block;margin:0;line-height:1.5}
#mv-layout-library .mv-fields :is(input:not([type=checkbox]),textarea){display:block;width:100%;max-width:100%;padding:11px 12px;margin:6px 0 0;border:1px solid #e0e9ec;background:#f7f9fa;border-radius:5px;color:var(--mv-ink);font-size:12px;line-height:1.5;min-height:0;height:auto;box-shadow:none}
#mv-layout-library .mv-fields input::placeholder,#mv-layout-library .mv-fields textarea::placeholder{color:#8499a2;opacity:1}
#mv-layout-library .mv-fields textarea{resize:vertical}
#mv-layout-library .mv-full{grid-column:1/-1}
#mv-layout-library fieldset{border:0;padding:0;margin:0;min-width:0}
